import { ChangeRequest } from '../domain/ChangeRequest';
import { RiskAssessment } from '../integrations/RiskProvider';

export interface IAIRiskAdvisor {
  predictFailureProbability(change: ChangeRequest): Promise<number>;
  recommendMitigations(change: ChangeRequest): Promise<string[]>;
}

export interface IAIImpactSummarizer {
  generateImpactSummary(change: ChangeRequest, dependencies: any[]): Promise<string>;
}

export interface IAICabAssistant {
  summarizeForCAB(change: ChangeRequest, risk: RiskAssessment): Promise<string>;
  recommendDecision(change: ChangeRequest): Promise<'Approve' | 'Reject' | 'MoreInfo'>;
}

export interface IAIRollbackPlanner {
  generateRollbackPlan(implementationPlan: string, affectedCIs: string[]): Promise<string>;
}

export interface IAIImplementationReviewer {
  reviewImplementationPlan(plan: string): Promise<string[]>; // Returns list of potential issues
}

export interface IAIChangeCommunicator {
  generateCommunicationDraft(change: ChangeRequest): Promise<string>;
}

export enum ChangeEventType {
  ChangeSubmitted = 'ChangeSubmitted',
  ImpactAnalysisCompleted = 'ImpactAnalysisCompleted',
  RiskAssessmentCompleted = 'RiskAssessmentCompleted',
  ApprovalRequested = 'ApprovalRequested',
  ApprovalGranted = 'ApprovalGranted',
  ApprovalRejected = 'ApprovalRejected',
  DeploymentScheduled = 'DeploymentScheduled',
  DeploymentStarted = 'DeploymentStarted',
  DeploymentSucceeded = 'DeploymentSucceeded',
  DeploymentFailed = 'DeploymentFailed',
  RollbackStarted = 'RollbackStarted',
  RollbackCompleted = 'RollbackCompleted',
  VerificationCompleted = 'VerificationCompleted',
  ChangeClosed = 'ChangeClosed'
}

export interface ChangeEvent {
  eventId: string;
  eventType: ChangeEventType;
  changeRequestId: string;
  timestamp: Date;
  payload: Record<string, any>;
}

export interface CI {
  ciId: string;
  name: string;
  businessCriticality: string;
}

export interface AssetProvider {
  getConfigurationItem(id: string): Promise<CI | null>;
  getDownstreamDependencies(ciId: string): Promise<CI[]>;
}

export class MockAssetProvider implements AssetProvider {
  async getConfigurationItem(id: string): Promise<CI | null> {
    return { ciId: id, name: `Mock Asset ${id}`, businessCriticality: 'MissionCritical' };
  }
  
  async getDownstreamDependencies(ciId: string): Promise<CI[]> {
    return [
      { ciId: 'db-1', name: 'Orders DB', businessCriticality: 'MissionCritical' },
      { ciId: 'cache-1', name: 'Redis Cache', businessCriticality: 'Important' }
    ];
  }
}

export interface ResilienceAssessment {
  violatesRTO: boolean;
  message: string;
}

export interface ResilienceProvider {
  validateRecoveryObjectives(ciIds: string[]): Promise<ResilienceAssessment>;
}

export class MockResilienceProvider implements ResilienceProvider {
  async validateRecoveryObjectives(ciIds: string[]): Promise<ResilienceAssessment> {
    return { violatesRTO: false, message: 'All dependencies meet required RTO' };
  }
}

export interface RiskAssessment {
  baseScore: number;
  factors: string[];
}

export interface RiskProvider {
  evaluateRisk(changeRequestId: string, payload: any): Promise<RiskAssessment>;
}

export class MockRiskProvider implements RiskProvider {
  async evaluateRisk(changeRequestId: string, payload: any): Promise<RiskAssessment> {
    return {
      baseScore: 45,
      factors: ['MissionCritical Asset', '2 Dependencies']
    };
  }
}

import { ChangeRequest } from '../domain/ChangeRequest';
import { ChangeState } from '../domain/ChangeState';
import { RiskEvaluator } from './RiskEvaluator';
import { ApprovalEngine } from './ApprovalEngine';
import { ApprovalStatus } from '../domain/Approval';
import { ResilienceProvider } from '../integrations/ResilienceProvider';
import { ChangeEventType, ChangeEvent } from '../events/ChangeEvents';

export class ChangeService {
  private events: ChangeEvent[] = [];

  constructor(
    private readonly riskEvaluator: RiskEvaluator,
    private readonly approvalEngine: ApprovalEngine,
    private readonly resilienceProvider: ResilienceProvider
  ) {}

  private emitEvent(eventType: ChangeEventType, change: ChangeRequest, payload: any = {}) {
    this.events.push({
      eventId: `evt-${Date.now()}`,
      eventType,
      changeRequestId: change.id,
      timestamp: new Date(),
      payload
    });
    console.log(`[Event] ${eventType} for Change ${change.id}`);
  }

  async submitChange(change: ChangeRequest): Promise<void> {
    if (change.state !== ChangeState.Draft) throw new Error('Only Draft changes can be submitted.');
    change.state = ChangeState.Submitted;
    this.emitEvent(ChangeEventType.ChangeSubmitted, change);
  }

  async assessImpactAndRisk(change: ChangeRequest): Promise<void> {
    if (change.state !== ChangeState.Submitted) throw new Error('Change must be Submitted.');
    
    // Impact analysis (via asset-core, abstracted for now)
    change.state = ChangeState.ImpactAssessed;
    this.emitEvent(ChangeEventType.ImpactAnalysisCompleted, change, { affectedCIs: change.affectedConfigurationItems });

    // Risk Assessment
    const riskScore = await this.riskEvaluator.calculateRisk(change);
    change.calculatedRiskScore = riskScore;
    change.state = ChangeState.RiskAssessed;
    this.emitEvent(ChangeEventType.RiskAssessmentCompleted, change, { riskScore });
    
    // Resilience Validation
    const resilience = await this.resilienceProvider.validateRecoveryObjectives(change.affectedConfigurationItems);
    if (resilience.violatesRTO) {
      throw new Error(`Resilience Validation Failed: ${resilience.message}`);
    }
  }

  async requestApprovals(change: ChangeRequest): Promise<void> {
    if (change.state !== ChangeState.RiskAssessed) throw new Error('Change must be Risk Assessed.');
    
    const approvals = await this.approvalEngine.evaluateApprovals(change);
    change.approvals = approvals;
    
    const allApproved = approvals.every(a => a.status === ApprovalStatus.Approved);
    
    if (allApproved) {
      change.state = ChangeState.Approved;
      this.emitEvent(ChangeEventType.ApprovalGranted, change);
    } else {
      change.state = ChangeState.AwaitingApproval;
      this.emitEvent(ChangeEventType.ApprovalRequested, change, { pendingApprovals: approvals });
    }
  }

  async scheduleDeployment(change: ChangeRequest): Promise<void> {
    if (change.state !== ChangeState.Approved) throw new Error('Change must be Approved.');
    change.state = ChangeState.Scheduled;
    this.emitEvent(ChangeEventType.DeploymentScheduled, change);
  }

  async startDeployment(change: ChangeRequest): Promise<void> {
    if (change.state !== ChangeState.Scheduled) throw new Error('Change must be Scheduled.');
    change.state = ChangeState.Executing;
    this.emitEvent(ChangeEventType.DeploymentStarted, change);
  }

  async completeDeployment(change: ChangeRequest, success: boolean): Promise<void> {
    if (change.state !== ChangeState.Executing) throw new Error('Change must be Executing.');
    if (success) {
      change.state = ChangeState.Verification;
      this.emitEvent(ChangeEventType.DeploymentSucceeded, change);
    } else {
      change.state = ChangeState.RolledBack;
      this.emitEvent(ChangeEventType.DeploymentFailed, change);
    }
  }

  async closeChange(change: ChangeRequest): Promise<void> {
    if (change.state !== ChangeState.Verification) throw new Error('Change must be in Verification to be closed.');
    change.state = ChangeState.Completed;
    this.emitEvent(ChangeEventType.VerificationCompleted, change);
    this.emitEvent(ChangeEventType.ChangeClosed, change);
  }
}

import { ChangeService } from './services/ChangeService';
import { RiskEvaluator } from './services/RiskEvaluator';
import { ApprovalEngine } from './services/ApprovalEngine';
import { MockAssetProvider } from './integrations/AssetProvider';
import { MockPolicyProvider } from './integrations/PolicyProvider';
import { MockResilienceProvider } from './integrations/ResilienceProvider';
import { ChangeRequest } from './domain/ChangeRequest';
import { ChangeState, ChangeCategory, ChangePriority } from './domain/ChangeState';

async function runTest() {
  console.log('--- Starting Enterprise Change Orchestration Test ---');

  // Initialize Providers (Ports & Adapters)
  const assetProvider = new MockAssetProvider();
  const policyProvider = new MockPolicyProvider();
  const resilienceProvider = new MockResilienceProvider();

  // Initialize Services
  const riskEvaluator = new RiskEvaluator(assetProvider);
  const approvalEngine = new ApprovalEngine(policyProvider);
  const changeService = new ChangeService(riskEvaluator, approvalEngine, resilienceProvider);

  // 1. Create a Normal Change Request
  const change: ChangeRequest = {
    id: 'CHG-2026-0801',
    title: 'Migrate Orders DB to new cluster',
    description: 'Upgrading the primary orders database for scale.',
    category: ChangeCategory.Normal,
    priority: ChangePriority.High,
    state: ChangeState.Draft,
    businessJustification: 'Capacity limits reached.',
    requesterId: 'usr-123',
    affectedBusinessCapabilities: ['cap-checkout'],
    affectedConfigurationItems: ['ci-orders-db'], // Mock provider treats this as MissionCritical
    implementationPlan: '...',
    rollbackPlan: '...',
    verificationPlan: '...',
    approvals: [],
    linkedIncidents: [],
    linkedProblems: [],
    auditReferences: [],
    createdAt: new Date(),
    updatedAt: new Date()
  };

  console.log(`\n[1] Submitting Change Request: ${change.id}`);
  await changeService.submitChange(change);

  console.log(`\n[2] Assessing Impact & Risk`);
  await changeService.assessImpactAndRisk(change);
  console.log(`    Calculated Risk Score: ${change.calculatedRiskScore}`);

  console.log(`\n[3] Requesting Approvals`);
  await changeService.requestApprovals(change);
  console.log(`    Change State: ${change.state}`);
  change.approvals.forEach(a => console.log(`    Required Approval: ${a.approvalType} (${a.status})`));

  // Simulate CAB Approval manually for the test
  if (change.state === ChangeState.AwaitingApproval) {
    console.log(`\n[4] Simulating CAB Approval...`);
    change.approvals.forEach(a => a.status = 'Approved' as any);
    // Since we mutated it manually, just force state to Approved for test flow
    change.state = ChangeState.Approved;
  }

  console.log(`\n[5] Scheduling & Executing`);
  await changeService.scheduleDeployment(change);
  await changeService.startDeployment(change);
  
  console.log(`\n[6] Deployment Succeeded, verifying...`);
  await changeService.completeDeployment(change, true);
  await changeService.closeChange(change);

  console.log(`\n--- Test Completed Successfully. Final State: ${change.state} ---`);
}

runTest().catch(console.error);
